create type public.record_consent_status as enum ('ACTIVE','REVOKED');
create table public.record_consents (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete cascade, doctor_id uuid not null references public.doctors(id) on delete cascade, status public.record_consent_status not null default 'ACTIVE', granted_at timestamptz not null default now(), revoked_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint record_consents_dates_check check (revoked_at is null or revoked_at >= granted_at), constraint record_consents_expiry_check check (expires_at is null or expires_at > granted_at), constraint record_consents_status_dates_check check ((status = 'ACTIVE' and revoked_at is null) or (status = 'REVOKED' and revoked_at is not null)), constraint record_consents_patient_doctor_unique unique (patient_id, doctor_id));
create index record_consents_patient_status_idx on public.record_consents (patient_id, status, expires_at); create index record_consents_doctor_status_idx on public.record_consents (doctor_id, status, expires_at); alter table public.record_consents enable row level security;
create or replace function public.set_record_consent_updated_at() returns trigger language plpgsql security invoker set search_path = public as $$ begin new.updated_at = now(); return new; end; $$; drop trigger if exists record_consents_set_updated_at on public.record_consents; create trigger record_consents_set_updated_at before update on public.record_consents for each row execute function public.set_record_consent_updated_at();
create or replace function public.has_valid_record_consent(p_patient_id uuid, p_doctor_id uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.record_consents rc join public.doctors d on d.id = rc.doctor_id where rc.patient_id = p_patient_id and rc.doctor_id = p_doctor_id and d.approval_status = 'APPROVED' and rc.status = 'ACTIVE' and (rc.expires_at is null or rc.expires_at > now())); $$;
create or replace function public.current_doctor_id() returns uuid language sql stable security definer set search_path = public as $$ select d.id from public.doctors d where d.user_id = auth.uid() and d.approval_status = 'APPROVED' limit 1; $$;
create or replace function public.grant_record_consent(p_doctor_id uuid, p_expires_at timestamptz default null) returns public.record_consents language plpgsql security definer set search_path = public as $$ declare v_patient_id uuid; v_consent public.record_consents; begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; select p.id into v_patient_id from public.patients p where p.user_id = auth.uid(); if v_patient_id is null then raise exception using errcode = '42501', message = 'Only a patient can grant consent'; end if; if not exists (select 1 from public.doctors d where d.id = p_doctor_id and d.approval_status = 'APPROVED') then raise exception using errcode = '22023', message = 'Approved doctor not found'; end if; if p_expires_at is not null and p_expires_at <= now() then raise exception using errcode = '22023', message = 'Consent expiry must be in the future'; end if; insert into public.record_consents (patient_id, doctor_id, status, granted_at, revoked_at, expires_at) values (v_patient_id, p_doctor_id, 'ACTIVE', now(), null, p_expires_at) on conflict (patient_id, doctor_id) do update set status = 'ACTIVE', granted_at = now(), revoked_at = null, expires_at = excluded.expires_at returning * into v_consent; return v_consent; end; $$;
create or replace function public.revoke_record_consent(p_consent_id uuid) returns public.record_consents language plpgsql security definer set search_path = public as $$ declare v_consent public.record_consents; begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; select rc.* into v_consent from public.record_consents rc join public.patients p on p.id = rc.patient_id where rc.id = p_consent_id and (p.user_id = auth.uid() or public.is_admin()); if v_consent.id is null then raise exception using errcode = '42501', message = 'Consent not found or access denied'; end if; update public.record_consents set status = 'REVOKED', revoked_at = coalesce(revoked_at, now()) where id = p_consent_id returning * into v_consent; return v_consent; end; $$;
revoke all on function public.grant_record_consent(uuid, timestamptz) from public; grant execute on function public.grant_record_consent(uuid, timestamptz) to authenticated; revoke all on function public.revoke_record_consent(uuid) from public; grant execute on function public.revoke_record_consent(uuid) to authenticated;
create policy record_consents_select_patient on public.record_consents for select to authenticated using (exists (select 1 from public.patients p where p.id = patient_id and p.user_id = auth.uid())); create policy record_consents_select_doctor on public.record_consents for select to authenticated using (doctor_id = public.current_doctor_id() and status = 'ACTIVE' and (expires_at is null or expires_at > now())); create policy record_consents_select_admin on public.record_consents for select to authenticated using (public.is_admin()); create policy record_consents_insert_admin on public.record_consents for insert to authenticated with check (public.is_admin()); create policy record_consents_update_admin on public.record_consents for update to authenticated using (public.is_admin()) with check (public.is_admin()); create policy record_consents_delete_admin on public.record_consents for delete to authenticated using (public.is_admin());
drop policy if exists consultations_select_doctor on public.consultations; create policy consultations_select_doctor on public.consultations for select to authenticated using (public.owns_consultation_doctor(id) and public.has_valid_record_consent(patient_id, doctor_id)); drop policy if exists consultations_update_doctor on public.consultations; create policy consultations_update_doctor on public.consultations for update to authenticated using (public.owns_consultation_doctor(id) and public.has_valid_record_consent(patient_id, doctor_id)) with check (public.owns_consultation_doctor(id) and public.has_valid_record_consent(patient_id, doctor_id));
drop policy if exists prescriptions_select_doctor on public.prescriptions; create policy prescriptions_select_doctor on public.prescriptions for select to authenticated using (public.owns_prescription_doctor(id) and public.has_valid_record_consent(patient_id, doctor_id)); drop policy if exists prescriptions_update_doctor on public.prescriptions; create policy prescriptions_update_doctor on public.prescriptions for update to authenticated using (public.owns_prescription_doctor(id) and public.has_valid_record_consent(patient_id, doctor_id)) with check (public.owns_prescription_doctor(id) and public.has_valid_record_consent(patient_id, doctor_id)); drop policy if exists prescription_items_select_doctor on public.prescription_items; create policy prescription_items_select_doctor on public.prescription_items for select to authenticated using (exists (select 1 from public.prescriptions pr where pr.id = prescription_id and public.owns_prescription_doctor(pr.id) and public.has_valid_record_consent(pr.patient_id, pr.doctor_id))); drop policy if exists prescription_items_update_doctor on public.prescription_items; create policy prescription_items_update_doctor on public.prescription_items for update to authenticated using (exists (select 1 from public.prescriptions pr where pr.id = prescription_id and public.owns_prescription_doctor(pr.id) and public.has_valid_record_consent(pr.patient_id, pr.doctor_id))) with check (exists (select 1 from public.prescriptions pr where pr.id = prescription_id and public.owns_prescription_doctor(pr.id) and public.has_valid_record_consent(pr.patient_id, pr.doctor_id))); drop policy if exists prescription_items_delete_doctor on public.prescription_items; create policy prescription_items_delete_doctor on public.prescription_items for delete to authenticated using (exists (select 1 from public.prescriptions pr where pr.id = prescription_id and public.owns_prescription_doctor(pr.id) and public.has_valid_record_consent(pr.patient_id, pr.doctor_id)));
drop policy if exists medical_reports_select_doctor on public.medical_reports; create policy medical_reports_select_doctor on public.medical_reports for select to authenticated using (exists (select 1 from public.test_orders o join public.doctors d on d.id = o.doctor_id where o.id = test_order_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED' and public.has_valid_record_consent(patient_id, d.id)));
drop policy if exists medical_reports_storage_select on storage.objects; create policy medical_reports_storage_select on storage.objects for select to authenticated using (bucket_id = 'medical-reports' and (public.is_admin() or exists (select 1 from public.medical_reports mr where mr.storage_path = name and (exists (select 1 from public.patients p where p.id = mr.patient_id and p.user_id = auth.uid()) or exists (select 1 from public.test_orders o join public.doctors d on d.id = o.doctor_id where o.id = mr.test_order_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED' and public.has_valid_record_consent(mr.patient_id, d.id))))));
drop policy if exists health_timeline_select_doctor on public.health_timeline; create policy health_timeline_select_doctor on public.health_timeline for select to authenticated using (public.has_valid_record_consent(patient_id, public.current_doctor_id()) and (exists (select 1 from public.consultations c where c.id = consultation_id and c.doctor_id = public.current_doctor_id()) or exists (select 1 from public.test_orders o where o.id = test_order_id and o.doctor_id = public.current_doctor_id()) or exists (select 1 from public.prescriptions pr where pr.id = prescription_id and pr.doctor_id = public.current_doctor_id()) or exists (select 1 from public.medical_reports mr join public.test_orders o on o.id = mr.test_order_id where mr.id = medical_report_id and o.doctor_id = public.current_doctor_id())));
